package io.hanji;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

/**
 * Outgoing command log of one window, delivered to the page as Server-Sent Events.
 * <p>
 * Batches carry increasing sequence numbers (the SSE {@code id}), so a reconnecting {@code EventSource}
 * resumes via {@code Last-Event-ID}. The page acknowledges received batches, which trims the log.
 * The channel also tracks which page instance (a random id generated by each page load) is current,
 * to tell a fresh navigation from a reload and to ignore messages of retired pages.
 */
final class WindowChannel {

    enum Binding { FIRST, SAME, RELOAD, RETIRED, CLOSED }

    static final long HEARTBEAT_MILLIS = 2000;
    private static final int MAX_LOG = 20_000;
    private static final long NAVIGATION_TIMEOUT_MILLIS = 15_000;

    private record Batch(long seq, String json) {
    }

    private final ArrayDeque<Batch> log = new ArrayDeque<>();
    private final ArrayDeque<String> retired = new ArrayDeque<>();
    private long nextSeq = 1;
    private long pageStartSeq = 1;
    private String pageId;
    private boolean expecting = true;
    private long expectingSince = System.currentTimeMillis();
    private long lastClientSeq;
    private int epoch;
    private boolean closed;
    private int activeStreams;
    private long connections;
    // Ordering of page lifecycle events (a counter, so events within the same millisecond stay ordered)
    private long eventSeq;
    private long lastConnectSeq;
    private long lastUnloadSeq;
    private long lastDocumentSeq;
    private long lastDocumentAt;

    synchronized void push(String json) {
        if (closed) {
            return;
        }
        log.addLast(new Batch(nextSeq++, json));
        while (log.size() > MAX_LOG) {
            log.removeFirst();
        }
        notifyAll();
    }

    /** Everything pushed from now on belongs to the next page instance that connects. */
    synchronized void expectNewPage() {
        expecting = true;
        expectingSince = System.currentTimeMillis();
        pageStartSeq = nextSeq;
    }

    synchronized Binding bind(String pid) {
        if (closed) {
            return Binding.CLOSED;
        }
        if (pid.equals(pageId)) {
            return Binding.SAME;
        }
        if (retired.contains(pid)) {
            return Binding.RETIRED;
        }
        Binding result = expecting || pageId == null ? Binding.FIRST : Binding.RELOAD;
        if (pageId != null) {
            retired.addLast(pageId);
            if (retired.size() > 32) {
                retired.removeFirst();
            }
        }
        pageId = pid;
        expecting = false;
        lastClientSeq = 0;
        if (result == Binding.RELOAD) {
            pageStartSeq = nextSeq;
        }
        while (!log.isEmpty() && log.peekFirst().seq() < pageStartSeq) {
            log.removeFirst();
        }
        epoch++;
        notifyAll();
        return result;
    }

    /** Duplicate detection for page-to-Java batches (the page retries failed sends). */
    synchronized boolean acceptClientSeq(long seq) {
        if (seq <= lastClientSeq) {
            return false;
        }
        lastClientSeq = seq;
        return true;
    }

    synchronized void ack(long seq) {
        while (!log.isEmpty() && log.peekFirst().seq() <= seq) {
            log.removeFirst();
        }
    }

    /**
     * An HTML document of this window was requested. On a reload or navigation the browser requests the new
     * document before it unloads the old page, so this marks a page that is loading rather than closed.
     */
    synchronized void markDocumentRequest() {
        lastDocumentSeq = ++eventSeq;
        lastDocumentAt = System.currentTimeMillis();
    }

    /**
     * The page instance {@code pid} is unloading (its pagehide beacon). Returns false and changes nothing when that
     * page was already replaced: on slow machines the beacon of a reloaded page can arrive after the new page
     * connected, and must not make the window look closed.
     */
    synchronized boolean markUnload(String pid) {
        if (pageId != null && !pageId.equals(pid)) {
            return false;
        }
        lastUnloadSeq = ++eventSeq;
        return true;
    }

    synchronized void close() {
        closed = true;
        notifyAll();
    }

    /** Whether a page is (or is about to be) connected. Used to detect closed browser windows. */
    synchronized boolean isAlive() {
        if (closed) {
            return false;
        }
        long now = System.currentTimeMillis();
        if (expecting && now - expectingSince < NAVIGATION_TIMEOUT_MILLIS) {
            return true;
        }
        // a document was requested after the last connection: a reload is still loading, however slowly
        if (lastDocumentSeq > lastConnectSeq && now - lastDocumentAt < NAVIGATION_TIMEOUT_MILLIS) {
            return true;
        }
        return activeStreams > 0 && lastConnectSeq > lastUnloadSeq;
    }

    /**
     * Streams batches to one SSE connection until the connection breaks, is replaced by a newer
     * connection, or the channel is closed.
     */
    void stream(String lastEventId, OutputStream out) throws IOException {
        int myEpoch;
        long cursor;
        synchronized (this) {
            myEpoch = ++epoch;
            notifyAll();
            long resume = parseLong(lastEventId);
            cursor = resume >= pageStartSeq - 1 ? resume : pageStartSeq - 1;
            activeStreams++;
            connections++;
            lastConnectSeq = ++eventSeq;
        }
        try {
            out.write("retry: 1000\n\n".getBytes(StandardCharsets.UTF_8));
            out.flush();
            while (true) {
                List<Batch> toSend;
                boolean heartbeat = false;
                synchronized (this) {
                    long deadline = System.currentTimeMillis() + HEARTBEAT_MILLIS;
                    while (epoch == myEpoch && !closed && !hasAfter(cursor)) {
                        long wait = deadline - System.currentTimeMillis();
                        if (wait <= 0) {
                            heartbeat = true;
                            break;
                        }
                        try {
                            wait(wait);
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                            return;
                        }
                    }
                    if (epoch != myEpoch) {
                        return;
                    }
                    toSend = after(cursor);
                    if (toSend.isEmpty() && closed) {
                        return;
                    }
                }
                if (!toSend.isEmpty()) {
                    StringBuilder sb = new StringBuilder();
                    for (Batch b : toSend) {
                        sb.append("id: ").append(b.seq()).append("\ndata: ").append(b.json()).append("\n\n");
                        cursor = b.seq();
                    }
                    out.write(sb.toString().getBytes(StandardCharsets.UTF_8));
                    out.flush();
                } else if (heartbeat) {
                    out.write(":\n\n".getBytes(StandardCharsets.UTF_8));
                    out.flush();
                }
            }
        } finally {
            synchronized (this) {
                activeStreams--;
            }
        }
    }

    /** Number of event streams opened so far (for tests). */
    synchronized long connections() {
        return connections;
    }

    private boolean hasAfter(long cursor) {
        return !log.isEmpty() && log.peekLast().seq() > cursor;
    }

    private List<Batch> after(long cursor) {
        List<Batch> out = new ArrayList<>();
        for (Batch b : log) {
            if (b.seq() > cursor) {
                out.add(b);
            }
        }
        return out;
    }

    private static long parseLong(String s) {
        if (s == null || s.isBlank()) {
            return -1;
        }
        try {
            return Long.parseLong(s.trim());
        } catch (NumberFormatException e) {
            return -1;
        }
    }
}
